  __m256i x0a4 = _mm256_permute2x128_si256( d0, d4, 0x31 );
  __m256i x0a1 = _mm256_permute2x128_si256( d1, d5, 0x20 );
  __m256i x0a5 = _mm256_permute2x128_si256( d1, d5, 0x31 );
  __m256i x0a2 = _mm256_permute2x128_si256( d2, d6, 0x20 );
  __m256i x0a6 = _mm256_permute2x128_si256( d2, d6, 0x31 );
  __m256i x0a3 = _mm256_permute2x128_si256( d3, d7, 0x20 );
  __m256i x0a7 = _mm256_permute2x128_si256( d3, d7, 0x31 );
  __m256i x0b0 = _mm256_unpacklo_epi32( x0a0, x0a2 );
  __m256i x0b2 = _mm256_unpackhi_epi32( x0a0, x0a2 );
  __m256i x0b1 = _mm256_unpacklo_epi32( x0a1, x0a3 );
  __m256i x0b3 = _mm256_unpackhi_epi32( x0a1, x0a3 );
  __m256i x0b4 = _mm256_unpacklo_epi32( x0a4, x0a6 );
  __m256i x0b6 = _mm256_unpackhi_epi32( x0a4, x0a6 );
  __m256i x0b5 = _mm256_unpacklo_epi32( x0a5, x0a7 );
  __m256i x0b7 = _mm256_unpackhi_epi32( x0a5, x0a7 );
