  __m256i o01 = _mm256_unpackhi_epi32( x0b0, x0b1 );
  __m256i o02 = _mm256_unpacklo_epi32( x0b2, x0b3 );
  __m256i o03 = _mm256_unpackhi_epi32( x0b2, x0b3 );
  __m256i o04 = _mm256_unpacklo_epi32( x0b4, x0b5 );
  __m256i o05 = _mm256_unpackhi_epi32( x0b4, x0b5 );
  __m256i o06 = _mm256_unpacklo_epi32( x0b6, x0b7 );
  __m256i o07 = _mm256_unpackhi_epi32( x0b6, x0b7 );
