  __m256i x1a4 = _mm256_permute2x128_si256( d8, dc, 0x31 );
  __m256i x1a1 = _mm256_permute2x128_si256( d9, dd, 0x20 );
  __m256i x1a5 = _mm256_permute2x128_si256( d9, dd, 0x31 );
  __m256i x1a2 = _mm256_permute2x128_si256( da, de, 0x20 );
  __m256i x1a6 = _mm256_permute2x128_si256( da, de, 0x31 );
  __m256i x1a3 = _mm256_permute2x128_si256( db, df, 0x20 );
  __m256i x1a7 = _mm256_permute2x128_si256( db, df, 0x31 );
  __m256i x1b0 = _mm256_unpacklo_epi32( x1a0, x1a2 );
  __m256i x1b2 = _mm256_unpackhi_epi32( x1a0, x1a2 );
  __m256i x1b1 = _mm256_unpacklo_epi32( x1a1, x1a3 );
  __m256i x1b3 = _mm256_unpackhi_epi32( x1a1, x1a3 );
  __m256i x1b4 = _mm256_unpacklo_epi32( x1a4, x1a6 );
  __m256i x1b6 = _mm256_unpackhi_epi32( x1a4, x1a6 );
  __m256i x1b5 = _mm256_unpacklo_epi32( x1a5, x1a7 );
  __m256i x1b7 = _mm256_unpackhi_epi32( x1a5, x1a7 );
  __m256i o10 = _mm256_unpacklo_epi32( x1b0, x1b1 );
  __m256i o11 = _mm256_unpackhi_epi32( x1b0, x1b1 );
  __m256i o12 = _mm256_unpacklo_epi32( x1b2, x1b3 );
  __m256i o13 = _mm256_unpackhi_epi32( x1b2, x1b3 );
  __m256i o14 = _mm256_unpacklo_epi32( x1b4, x1b5 );
  __m256i o15 = _mm256_unpackhi_epi32( x1b4, x1b5 );
  __m256i o16 = _mm256_unpacklo_epi32( x1b6, x1b7 );
  __m256i o17 = _mm256_unpackhi_epi32( x1b6, x1b7 );
  _mm256_storeu_si256( (__m256i *)(out + 64UL*(8UL*t+0UL)), o00 ); _mm256_storeu_si256( (__m256i *)(out + 64UL*(8UL*t+0UL) + 32UL), o10 );
